import { requireActor, requirePermission, revalidateActor } from '@/server/permissions';
import { apiError, json, ApiError } from '@/server/http';
import { buildSitePackage } from '@/server/site-package';
import { STARTER_KITS, createStarterSnapshot } from '@/lib/starter-kits';
export const runtime = 'nodejs';
export async function GET(request: Request, { params }: { params: Promise<{kind:string}> }) {
  try {
    let actor=await requireActor(request);requirePermission(actor,'manage');const {kind}=await params;
    // 套件入口仍按当前管理员会话授权，不沿用等待参数前的身份。
    actor=revalidateActor(actor,'manage');
    const kit=STARTER_KITS.find(k=>k.id===kind);if(!kit)throw new ApiError(404,'演示套件不存在');
    return json(buildSitePackage(createStarterSnapshot(kit.id),{name:kit.name,description:kit.description,license:'Original synthetic demonstration layouts. No customer results, certifications, photography or redistribution rights are asserted. Replace with verified, authorized customer information.'}));
  } catch(e){return apiError(e);}
}
